node --input-type=module <<'JS'
import {writeFile} from 'node:fs/promises';
const targets=await (await fetch('http://localhost:9222/json')).json();
const page=targets.find(x=>x.type==='page');
if(!page) throw Error('no page target');
const ws=new WebSocket(page.webSocketDebuggerUrl);
await new Promise((ok,no)=>{ws.onopen=ok;ws.onerror=no});
let id=0,waiters=new Map();
ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&waiters.has(m.id)){waiters.get(m.id)(m);waiters.delete(m.id)}};
const call=(method,params={})=>new Promise(resolve=>{const n=++id;waiters.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}))});
await call('Page.enable');
await call('Runtime.evaluate',{expression:"document.querySelector('#startBtn').click()"});
await new Promise(r=>setTimeout(r,1400));
const out=await call('Page.captureScreenshot',{format:'jpeg',quality:78,fromSurface:true});
await writeFile('/tmp/gb27.jpg',Buffer.from(out.result.data,'base64'));
const status=await call('Runtime.evaluate',{expression:"JSON.stringify({title:document.querySelector('#modalTitle').textContent,score:document.querySelector('#shardVal').textContent,canvas:[document.querySelector('canvas').width,document.querySelector('canvas').height]})",returnByValue:true});
console.log(status.result.result.value);
ws.close();
